import React, { useEffect, useMemo, useState } from "react";
import { Card, Typography, Row, Col, Statistic, Progress, Timeline, Tag, Button, Space, Tabs, Alert, Table, Modal, Form, Input, Switch, message, Spin, Popconfirm, Select } from "antd";
import { 
  BrainCircuitIcon, 
  ActivityIcon, 
  NetworkIcon, 
  TrendingUpIcon,
  SettingsIcon,
  ZapIcon,
  EyeIcon
} from "lucide-react";
import { DeleteOutlined } from "@ant-design/icons";
import { getTelegramUser, apiRequest } from "../api";
import TraceViewer from "../components/TraceViewer";

const { Title, Text } = Typography;

interface SoulMetrics {
  total_quants: number;
  active_goals: number;
  avg_energy: number;
  connection_strength: number;
  sleep_cycles: number;
  optimization_score: number;
  recent_activity?: {
    recent_quants?: number;
    recent_sleep_cycles?: number;
    high_energy_quants?: number;
    strong_connections?: number;
  };
}

interface RecentActivity {
  id: string;
  type: string;
  event_type?: string;
  description: string;
  timestamp: string;
  importance: "low" | "medium" | "high";
  metadata?: any;
}

export default function SoulDashboard() {
  const [loading, setLoading] = useState(true);
  const [metrics, setMetrics] = useState<SoulMetrics | null>(null);
  const [recentActivity, setRecentActivity] = useState<RecentActivity[]>([]);
  const [systemStatus, setSystemStatus] = useState<"healthy" | "warning" | "critical">("healthy");
  const [goals, setGoals] = useState<Array<any>>([]);
  const [goalsFilter, setGoalsFilter] = useState<'all'|'goals'|'k0'>('goals');
  const [goalsLoading, setGoalsLoading] = useState<boolean>(false);
  const [goalModalOpen, setGoalModalOpen] = useState<boolean>(false);
  const [goalLoading, setGoalLoading] = useState<boolean>(false);
  const [currentGoalId, setCurrentGoalId] = useState<string | null>(null);
  const [goalForm] = Form.useForm();
  const [autoGenLoading, setAutoGenLoading] = useState<boolean>(false);
  const [dashDispEnabled, setDashDispEnabled] = useState<boolean>(false);
  const [dashDispBusy, setDashDispBusy] = useState<boolean>(false);

  // Quant details modal
  const [quantModalOpen, setQuantModalOpen] = useState<boolean>(false);
  const [currentQuantId, setCurrentQuantId] = useState<string | null>(null);
  const [quantDetailLoading, setQuantDetailLoading] = useState<boolean>(false);
  const [quantDetail, setQuantDetail] = useState<any | null>(null);
  const [relatedQuants, setRelatedQuants] = useState<Array<{ id: string; strength?: number; head?: string }>>([]);
  // Фильтр «только Соул» для таблицы аудита
  const [onlySoul, setOnlySoul] = useState<boolean>(false);
  // Локальная форма тестовой генерации
  const [testText, setTestText] = useState<string>("");
  const [genLoading, setGenLoading] = useState<boolean>(false);
  // Trace Viewer
  const [traceViewerOpen, setTraceViewerOpen] = useState<boolean>(false);
  const [traceId, setTraceId] = useState<string | undefined>(undefined);
  const [traceQuantId, setTraceQuantId] = useState<string | undefined>(undefined);
  const [traceThreadId, setTraceThreadId] = useState<string | undefined>(undefined);
  // Детали события
  const [eventModalOpen, setEventModalOpen] = useState<boolean>(false);
  const [selectedEvent, setSelectedEvent] = useState<RecentActivity | null>(null);
  // Фильтр ошибок для таблицы
  const [onlyErrors, setOnlyErrors] = useState<boolean>(false);
  // Помощник: ищем quant_id для активности (по UUID в описании или по ближайшему времени)
  const resolveQuantIdByActivity = async (activity: RecentActivity): Promise<string | null> => {
    try {
      // 0) metadata.quant_id
      const metaQ = (activity as any)?.metadata?.quant_id;
      if (metaQ && typeof metaQ === 'string' && metaQ.length >= 36) return metaQ;
      // 0.1) id вида quant_<uuid>
      if (activity.id && activity.id.startsWith('quant_')) {
        const qidFromId = activity.id.slice('quant_'.length);
        if (qidFromId && qidFromId.length >= 36) return qidFromId;
      }
      // 1) Пробуем вытащить UUID из текста
      const m = String(activity.description || '').match(/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}/);
      if (m && m[0]) return m[0];
      // 2) Берём последние кванты и ищем ближайший по времени
      const resp = await apiRequest(`/admin/soul/graph/recent_quants?limit=50`, 'GET');
      const items: Array<any> = Array.isArray(resp?.items) ? resp.items : (Array.isArray(resp) ? resp : []);
      if (!items.length) return null;
      const targetTs = new Date(activity.timestamp).getTime();
      let best: { id: string; dt: number } | null = null;
      for (const it of items) {
        const id = String(it.id || it.quant_id || '');
        const dt = new Date(it.created_at || it.ts || Date.now()).getTime();
        if (!id) continue;
        const d = Math.abs(dt - targetTs);
        if (!best || d < best.dt) best = { id, dt: d };
      }
      return best ? best.id : null;
    } catch {
      return null;
    }
  };


  const loadDashboardData = async () => {
    try {
      setLoading(true);
      
      // Загружаем метрики Soul
      try {
        const metricsData = await apiRequest("/admin/soul/metrics/dashboard", "GET");
        setMetrics(metricsData);
      } catch (error) {
        console.error("Ошибка загрузки метрик:", error);
      }

      // Загружаем недавнюю активность
      try {
        const activityData = await apiRequest("/admin/soul/metrics/activity/recent?limit=20&exclude_test=false", "GET");
        setRecentActivity(activityData.items || []);
      } catch (error) {
        console.error("Ошибка загрузки активности:", error);
      }

      // Загружаем цели с кратким содержанием Квантов
      try {
        setGoalsLoading(true);
        const goalsData = await apiRequest("/admin/soul/goals?limit=500&exclude_test=false", "GET");
        setGoals(Array.isArray(goalsData.items) ? goalsData.items : []);
      } catch (error) {
        console.error("Ошибка загрузки целей:", error);
      } finally {
        setGoalsLoading(false);
      }

      // Определяем статус системы
      if (metrics) {
        if (metrics.avg_energy < 0.3 || metrics.optimization_score < 0.5) {
          setSystemStatus("critical");
        } else if (metrics.avg_energy < 0.5 || metrics.optimization_score < 0.7) {
          setSystemStatus("warning");
        } else {
          setSystemStatus("healthy");
        }
      }

    } catch (error) {
      console.error("Ошибка загрузки данных дашборда:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDashboardData();
    // Загрузка состояния авторежима (диспетчер)
    (async () => {
      try {
        const s = await apiRequest('/admin/dispatcher/settings', 'GET');
        setDashDispEnabled(!!s?.dispatcher_enabled);
      } catch {
        // no-op
      }
    })();
    
    // Автообновление каждые 30 секунд
    const interval = setInterval(loadDashboardData, 30000);
    return () => clearInterval(interval);
  }, []);

  const openGoalModal = async (goalId: string) => {
    try {
      setGoalLoading(true);
      setCurrentGoalId(goalId);
      const details = await apiRequest(`/admin/soul/goals/${goalId}`, "GET");
      // Заполняем форму доступными полями
      goalForm.setFieldsValue({
        title: details.title ?? "",
        description: details.description ?? "",
        priority: details.priority ?? 0.5,
        is_active: typeof details.is_active === "boolean" ? details.is_active : (details.status ? details.status === "active" : true),
        quant_id: details.quant_id,
      });
      setGoalModalOpen(true);
    } catch (e: any) {
      message.error("Не удалось загрузить цель");
    } finally {
      setGoalLoading(false);
    }
  };

  const saveGoal = async () => {
    try {
      const values = await goalForm.validateFields();
      if (!currentGoalId) return;
      const payload: any = {
        quant_id: values.quant_id,
        priority: Number(values.priority ?? 0.5),
        is_active: !!values.is_active,
      };
      if (values.title !== undefined) payload.title = values.title;
      if (values.description !== undefined) payload.description = values.description;
      await apiRequest(`/admin/soul/goals/${currentGoalId}`, "PUT", payload);
      message.success("Цель обновлена");
      setGoalModalOpen(false);
      setCurrentGoalId(null);
      await loadDashboardData();
    } catch (e: any) {
      if (e?.message) message.error(e.message);
      else message.error("Ошибка сохранения цели");
    }
  };

  const openQuantModal = async (quantId: string) => {
    try {
      setQuantDetailLoading(true);
      setCurrentQuantId(quantId);
      // 1) Основная информация по Кванту
      const q = await apiRequest(`/soul/quant/${quantId}`, "GET");
      // Нормализуем теги в массив строк
      const normTags = Array.isArray(q?.tags)
        ? (q.tags as any[]).map((t: any) => String(t))
        : (typeof q?.tags === 'string')
          ? [String(q.tags)]
          : Array.isArray(q?.payload?.tags)
            ? (q.payload.tags as any[]).map((t: any) => String(t))
            : [];
      setQuantDetail({ ...(q || {}), tags: normTags });
      // 2) Связанные кванты (берём сильные рёбра и фильтруем по quantId)
      const edgesResp = await apiRequest(`/admin/soul/graph/strong_edges?min_strength=0&limit=200`, "GET");
      const edges: Array<any> = Array.isArray(edgesResp?.items) ? edgesResp.items : (Array.isArray(edgesResp) ? edgesResp : []);
      const rel: Array<{ id: string; strength?: number }> = [];
      edges.forEach((e: any) => {
        const fromId = String(e.from_quant_id || e.source || e.from || "");
        const toId = String(e.to_quant_id || e.target || e.to || "");
        const strength = Number(e.connection_strength || e.strength || 0);
        if (fromId === quantId && toId) rel.push({ id: toId, strength });
        else if (toId === quantId && fromId) rel.push({ id: fromId, strength });
      });
      // Уникализируем и сортируем по силе
      const uniqMap = new Map<string, number>();
      rel.forEach(r => {
        const prev = uniqMap.get(r.id) || 0;
        if ((r.strength || 0) > prev) uniqMap.set(r.id, r.strength || 0);
      });
      const top = Array.from(uniqMap.entries())
        .map(([id, s]) => ({ id, strength: s }))
        .sort((a, b) => (b.strength || 0) - (a.strength || 0))
        .slice(0, 5);
      // Подгрузим заголовки (snippet)
      const detailed: Array<{ id: string; strength?: number; head?: string }> = [];
      for (const t of top) {
        try {
          const qi = await apiRequest(`/soul/quant/${t.id}`, "GET");
          detailed.push({ id: t.id, strength: t.strength, head: String(qi?.thought_form || "").slice(0, 140) });
        } catch {
          detailed.push({ id: t.id, strength: t.strength });
        }
      }
      setRelatedQuants(detailed);
      setQuantModalOpen(true);
    } catch (e: any) {
      message.error('Ошибка загрузки Кванта');
      setQuantDetail(null as any);
    } finally {
      setQuantDetailLoading(false);
    }
  };

  // Смарт‑открытие: при 404 пробуем ближайший по времени квант
  const openQuantModalSmart = async (activity: RecentActivity) => {
    // первичный id
    const primaryId = await resolveQuantIdByActivity(activity);
    if (primaryId) {
      try {
        // Пробный запрос, чтобы не гасить 404 внутри openQuantModal
        const q = await apiRequest(`/soul/quant/${primaryId}`, 'GET');
        if (q) {
          await openQuantModal(primaryId);
          return;
        }
      } catch {
        // продолжаем к fallback
      }
    }
    try {
      const resp = await apiRequest(`/admin/soul/graph/recent_quants?limit=20`, 'GET');
      const items: Array<any> = Array.isArray(resp?.items) ? resp.items : (Array.isArray(resp) ? resp : []);
      if (!items.length) {
        message.warning('Кванты не найдены');
        return;
      }
      const targetTs = new Date(activity.timestamp).getTime();
      // сортируем по близости ко времени активности
      const ranked = items
        .map(it => ({
          id: String(it.id || it.quant_id || ''),
          dt: Math.abs(new Date(it.created_at || it.ts || Date.now()).getTime() - targetTs)
        }))
        .filter(x => x.id)
        .sort((a, b) => a.dt - b.dt)
        .slice(0, 5);
      // ищем первый доступный без 404
      for (const cand of ranked.length ? ranked : [{ id: String(items[0].id || items[0].quant_id || '') } as any]) {
        try {
          const q = await apiRequest(`/soul/quant/${cand.id}`, 'GET');
          if (q) {
            await openQuantModal(cand.id);
            return;
          }
        } catch {
          // пробуем следующий
        }
      }
      // Как последний резерв: показываем краткую карточку ближайшего кванта без детальной загрузки
      const fallbackList = await apiRequest(`/admin/soul/graph/recent_quants?limit=5`, 'GET');
      const items2: Array<any> = Array.isArray(fallbackList?.items) ? fallbackList.items : (Array.isArray(fallbackList) ? fallbackList : []);
      if (items2.length) {
        const item0 = items2[0];
        setCurrentQuantId(String(item0.id || item0.quant_id || ''));
        setQuantDetail({
          id: String(item0.id || item0.quant_id || ''),
          thought_form: item0.thought_form || '(нет данных) — ограниченный просмотр',
          energy_weight: item0.energy_weight ?? 0,
          tags: [],
          created_at: item0.created_at || null,
          _limited: true
        } as any);
        setRelatedQuants([]);
        setQuantModalOpen(true);
        return;
      }
      message.warning('Не удалось открыть ни один из ближайших Квантов');
    } catch {
      message.error('Ошибка поиска ближайшего Кванта');
    }
  };

  // Функции для Trace Viewer
  const openTraceByActivity = (activity: RecentActivity) => {
    // Пытаемся извлечь trace_id из метаданных активности
    const activityTraceId = (activity as any)?.metadata?.trace_id;
    if (activityTraceId) {
      setTraceId(activityTraceId);
      setTraceQuantId(undefined);
      setTraceThreadId(undefined);
      setTraceViewerOpen(true);
    } else {
      // Если нет trace_id, пробуем по quant_id
      resolveQuantIdByActivity(activity).then(quantId => {
        if (quantId) {
          setTraceId(undefined);
          setTraceQuantId(quantId);
          setTraceThreadId(undefined);
          setTraceViewerOpen(true);
        } else {
          message.warning('Не удалось найти трассировку для данного события');
        }
      });
    }
  };

  const openTraceByQuantId = (quantId: string) => {
    setTraceId(undefined);
    setTraceQuantId(quantId);
    setTraceThreadId(undefined);
    setTraceViewerOpen(true);
  };

  const closeTraceViewer = () => {
    setTraceViewerOpen(false);
    setTraceId(undefined);
    setTraceQuantId(undefined);
    setTraceThreadId(undefined);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "healthy": return "#52c41a";
      case "warning": return "#faad14";
      case "critical": return "#f5222d";
      default: return "#d9d9d9";
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "healthy": return "Система работает нормально";
      case "warning": return "Требуется внимание";
      case "critical": return "Критические проблемы";
      default: return "Неизвестно";
    }
  };

  const getActivityIcon = (type: string) => {
    switch (type) {
      case "quant_created": return <BrainCircuitIcon size={16} />;
      case "sleep_cycle": return <ZapIcon size={16} />;
      case "optimization": return <TrendingUpIcon size={16} />;
      case "connection": return <NetworkIcon size={16} />;
      case "error": return <ZapIcon color="#f5222d" size={16} />;
      case "soul_step": return <ActivityIcon size={16} />;
      default: return <ActivityIcon size={16} />;
    }
  };

  const getActivityColor = (importance: string) => {
    switch (importance) {
      case "high": return "red";
      case "medium": return "orange";
      case "low": return "blue";
      default: return "default";
    }
  };

  const getEventIcon = (eventType: string) => {
    switch (eventType) {
      case "quant_created": return <BrainCircuitIcon size={16} />;
      case "sleep_cycle": return <ZapIcon size={16} />;
      case "optimization": return <TrendingUpIcon size={16} />;
      case "connection": return <NetworkIcon size={16} />;
      case "error": return <ZapIcon color="#f5222d" size={16} />;
      case "soul_llm": return <ActivityIcon size={16} />;
      case "router": return <NetworkIcon size={16} />;
      case "parser": return <BrainCircuitIcon size={16} />;
      case "refiner": return <BrainCircuitIcon size={16} />;
      case "batch": return <NetworkIcon size={16} />;
      case "process": return <ActivityIcon size={16} />;
      case "sleep": return <ZapIcon size={16} />;
      case "goal": return <EyeIcon size={16} />;
      default: return <ActivityIcon size={16} />;
    }
  };

  const getEventColor = (eventType: string) => {
    switch (eventType) {
      case "quant_created": return "green";
      case "sleep_cycle": return "blue";
      case "optimization": return "purple";
      case "connection": return "geekblue";
      case "error": return "red";
      case "soul_llm": return "cyan";
      case "router": return "orange";
      case "parser": return "magenta";
      case "refiner": return "purple";
      case "batch": return "geekblue";
      case "process": return "cyan";
      case "sleep": return "blue";
      case "goal": return "geekblue";
      default: return "default";
    }
  };

  const formatTimestamp = (ts: string) => {
    const date = new Date(ts);
    return `${date.toLocaleDateString()} ${date.toLocaleTimeString()}`;
  };

  const renderEventDetails = (event: any) => {
    if (!event.meta) return null;
    const details = Object.entries(event.meta)
      .filter(([key, value]) => value !== null && value !== undefined)
      .map(([key, value]) => (
        <Tag key={key} color="blue" style={{ marginRight: 4 }}>
          {key}: {String(value)}
        </Tag>
      ));
    return details.length > 0 ? <div style={{ marginTop: 6 }}>{details}</div> : null;
  };

  return (
    <div style={{ padding: 24 }}>
      <div style={{ marginBottom: 24 }}>
        <Title level={2}>
          <BrainCircuitIcon style={{ marginRight: 8, verticalAlign: "middle" }} />
          Soul Dashboard
        </Title>
        <Text type="secondary">Мониторинг и управление системой Soul</Text>
      </div>

      {/* Статус системы */}
      <Alert
        message={`Статус системы: ${getStatusText(systemStatus)}`}
        type={systemStatus === "healthy" ? "success" : systemStatus === "warning" ? "warning" : "error"}
        showIcon
        style={{ marginBottom: 24 }}
        action={
          <Button size="small" onClick={loadDashboardData}>
            Обновить
          </Button>
        }
      />

      {/* Основные метрики */}
      {/* Системные показатели (подняты сразу под основными метриками) */}
      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Всего Квантов"
              value={metrics?.total_quants || 0}
              prefix={<BrainCircuitIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Активные Цели"
              value={metrics?.active_goals || 0}
              prefix={<EyeIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Средняя Энергия"
              value={metrics?.avg_energy || 0}
              precision={2}
              suffix="%"
              prefix={<ZapIcon size={20} />}
              loading={loading}
            />
            <Progress 
              percent={(metrics?.avg_energy || 0) * 100} 
              size="small" 
              strokeColor={getStatusColor(systemStatus)}
              showInfo={false}
              style={{ marginTop: 8 }}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Сила Связей"
              value={metrics?.connection_strength || 0}
              precision={2}
              prefix={<NetworkIcon size={20} />}
              loading={loading}
            />
            <Progress 
              percent={(metrics?.connection_strength || 0) * 100} 
              size="small" 
              strokeColor="#1890ff"
              showInfo={false}
              style={{ marginTop: 8 }}
            />
          </Card>
        </Col>
      </Row>

      {/* Активность за 24 часа */}
      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Новые Кванты (24ч)"
              value={metrics?.recent_activity?.recent_quants || 0}
              prefix={<BrainCircuitIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Высокоэнерг. Кванты (24ч)"
              value={metrics?.recent_activity?.high_energy_quants || 0}
              prefix={<ZapIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Сильные Связи (24ч)"
              value={metrics?.recent_activity?.strong_connections || 0}
              prefix={<NetworkIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} md={6}>
          <Card>
            <Statistic
              title="Циклы Сна (24ч)"
              value={metrics?.recent_activity?.recent_sleep_cycles || 0}
              prefix={<ZapIcon size={20} />}
              loading={loading}
            />
          </Card>
        </Col>
      </Row>

      <Row gutter={[16, 16]}>
        {/* Недавняя активность */}
        <Col xs={24} lg={12}>
          <Card 
            title="Недавняя Активность" 
            extra={<Button size="small" onClick={loadDashboardData}>Обновить</Button>}
          >
            <Timeline
              mode="left"
              items={recentActivity.map(activity => ({
                dot: getActivityIcon(activity.type),
                children: (
                  <div>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <div>
                        <Text strong>{activity.description}</Text>
                        {/* Важные индикаторы */}
                        <div style={{ marginTop: 4 }}>
                          <Space size={6} wrap>
                            {(activity as any)?.event_type && <Tag color="geekblue">{(activity as any).event_type}</Tag>}
                            {activity.type === 'error' && <Tag color="red">error</Tag>}
                          </Space>
                        </div>
                      </div>
                      <Tag color={getActivityColor(activity.importance)}>
                        {activity.importance}
                      </Tag>
                    </div>
                    <Text type="secondary" style={{ fontSize: 12 }}>
                      {new Date(activity.timestamp).toLocaleString()}
                    </Text>
                    <div style={{ marginTop: 6 }}>
                      <Space size={8} wrap>
                        <Button size="small" type="link" onClick={() => { setSelectedEvent(activity); setEventModalOpen(true); }}>Подробнее</Button>
                        <Button size="small" onClick={async () => { await openQuantModalSmart(activity); }}>Открыть связанный квант</Button>
                      </Space>
                    </div>
                  </div>
                )
              }))}
            />
            {recentActivity.length === 0 && (
              <Text type="secondary">Нет недавней активности</Text>
            )}
          </Card>
        </Col>

        {/* Системные показатели */}
        <Col xs={24} lg={12}>
          <Card title="Системные Показатели" extra={<Button size="small" onClick={loadDashboardData}>Обновить</Button>}>
            <Row gutter={[16, 16]}>
              <Col span={12}>
                <Statistic
                  title="Циклы Сна"
                  value={metrics?.sleep_cycles || 0}
                  loading={loading}
                />
              </Col>
              <Col span={12}>
                <Statistic
                  title="Оптимизация"
                  value={metrics?.optimization_score || 0}
                  precision={2}
                  suffix="/1.0"
                  loading={loading}
                />
              </Col>
            </Row>
            
            <div style={{ marginTop: 16 }}>
              <Text strong>Производительность системы:</Text>
              <Progress 
                percent={(metrics?.optimization_score || 0) * 100} 
                strokeColor={getStatusColor(systemStatus)}
                style={{ marginTop: 8 }}
              />
            </div>

            {/* Быстрые действия в компактном едином стиле */}
            <div style={{ marginTop: 16 }}>
              <Text strong>Быстрые действия</Text>
              <div style={{ marginTop: 8 }}>
                <Space wrap size={8}>
                  <Button size="small" type="primary" icon={<SettingsIcon size={14} />} onClick={() => window.location.replace('/architect')}>Архитектор</Button>
                  <Button size="small" icon={<TrendingUpIcon size={14} />} onClick={() => window.location.href = '/soul/optimization'}>Оптимизация</Button>
                  <Button size="small" icon={<NetworkIcon size={14} />} onClick={() => window.location.href = '/soul/visualization'}>Визуализация</Button>
                  <Button size="small" icon={<ZapIcon size={14} />} onClick={async () => {
                    try { await apiRequest('/soul/sleep', 'POST'); message.success('Сон запущен'); loadDashboardData(); }
                    catch { message.error('Ошибка запуска сна'); }
                  }}>Сон</Button>
                  <Space size={8} align="center">
                    <Text style={{ fontSize: 12 }}>Авторежим</Text>
                    <Switch size="small" checked={dashDispEnabled} loading={dashDispBusy} onChange={async (v) => {
                      try { setDashDispBusy(true); await apiRequest('/admin/dispatcher/settings', 'PUT', { dispatcher_enabled: v }); setDashDispEnabled(v); message.success(v ? 'Включен' : 'Выключен'); }
                      catch { message.error('Не удалось обновить'); }
                      finally { setDashDispBusy(false); }
                    }} />
                  </Space>
                  <Button size="small" type="dashed" loading={autoGenLoading} icon={<BrainCircuitIcon size={14} />} onClick={async () => {
                    try { setAutoGenLoading(true); const plan = await apiRequest('/admin/dispatcher/plan_once', 'POST'); const mat = await apiRequest('/admin/dispatcher/materialize_once', 'POST'); message.success(`Планировано: ${Number(plan?.planned||0)}, отправлено: ${Number(mat?.dispatched||0)}`); loadDashboardData(); }
                    catch { message.error('Не удалось запустить'); }
                    finally { setAutoGenLoading(false); }
                  }}>Автоген</Button>
                </Space>
              </div>
            </div>
          </Card>
        </Col>
      </Row>
      {/* Таблица Квантов перенесена на страницу «Кванты». */}

      <Modal
        title="Цель"
        open={goalModalOpen}
        confirmLoading={goalLoading}
        onCancel={() => { setGoalModalOpen(false); setCurrentGoalId(null); }}
        onOk={saveGoal}
        okText="Сохранить"
        cancelText="Отмена"
        destroyOnClose
      >
        <Form form={goalForm} layout="vertical">
          <Form.Item name="quant_id" label="Quant ID" rules={[{ required: true, message: 'Укажите Quant ID' }]}>
            <Input disabled />
          </Form.Item>
          <Form.Item name="title" label="Заголовок">
            <Input placeholder="Название цели" maxLength={200} />
          </Form.Item>
          <Form.Item name="description" label="Описание">
            <Input.TextArea rows={6} placeholder="Описание цели" />
          </Form.Item>
          <Form.Item name="priority" label="Приоритет (0..1)" rules={[{ required: true, message: 'Укажите приоритет' }]}>
            <Input type="number" min={0} max={1} step={0.01} />
          </Form.Item>
          <Form.Item name="is_active" label="Активна" valuePropName="checked">
            <Switch />
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        title={`Квант ${currentQuantId ?? ''}`}
        open={quantModalOpen}
        onCancel={() => { setQuantModalOpen(false); setCurrentQuantId(null); }}
        footer={<div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
          <Button onClick={() => { setQuantModalOpen(false); setCurrentQuantId(null); }}>Закрыть</Button>
          <Button onClick={async () => {
            try {
              if (!currentQuantId) return;
              const q = await apiRequest(`/admin/soul/quant/smart?quant_id=${currentQuantId}`, 'GET');
              const normTags = Array.isArray(q?.tags)
                ? (q.tags as any[]).map((t: any) => String(t))
                : (typeof q?.tags === 'string') ? [String(q.tags)] : [];
              setQuantDetail({ ...(q || {}), tags: normTags });
              message.success('Загружены подробные данные');
            } catch { message.error('Не удалось загрузить подробные данные'); }
          }}>Открыть детально (умно)</Button>
          <Button type="primary" onClick={async () => {
            try {
              if (!currentQuantId || !quantDetail) return;
              const patch: any = {
                thought_form: quantDetail.thought_form,
                energy_weight: quantDetail.energy_weight,
                tags: quantDetail.tags,
                payload: quantDetail.payload,
                composite_emotion: quantDetail.composite_emotion
              };
              await apiRequest(`/admin/soul/quant/${currentQuantId}`, 'PUT', patch);
              message.success('Квант обновлён');
            } catch (e) {
              message.error('Ошибка сохранения кванта');
            }
          }}>Сохранить</Button>
        </div>}
        width={800}
        destroyOnClose
      >
        <Spin spinning={quantDetailLoading}>
          {quantDetail ? (
            <div>
              <Title level={4} style={{ marginTop: 0 }}>Мысль</Title>
              <Typography.Paragraph>
                <textarea
                  value={quantDetail.thought_form || ''}
                  onChange={e => setQuantDetail((prev: any) => ({ ...(prev||{}), thought_form: e.target.value }))}
                  style={{ width: '100%', minHeight: 80 }}
                />
              </Typography.Paragraph>
              <Row gutter={16}>
                <Col span={8}>
                  <Statistic title="Энергия" value={quantDetail.energy_weight ?? 0} precision={2} />
                  <input
                    type="number"
                    step="0.01"
                    min={0}
                    max={1}
                    value={quantDetail.energy_weight ?? 0}
                    onChange={e => setQuantDetail((prev: any) => ({ ...(prev||{}), energy_weight: parseFloat(e.target.value) }))}
                    style={{ width: '100%', marginTop: 8 }}
                  />
                </Col>
                <Col span={8}><Statistic title="Создан" value={quantDetail.created_at || '-'} /></Col>
              </Row>
              <div style={{ marginTop: 12 }}>
                <Text strong>Теги:</Text>
                <div style={{ marginTop: 6 }}>
                  <input
                    value={(quantDetail.tags || []).join(', ')}
                    onChange={e => setQuantDetail((prev: any) => ({ ...(prev||{}), tags: e.target.value.split(',').map(s => s.trim()).filter(Boolean) }))}
                    style={{ width: '100%' }}
                  />
                </div>
              </div>
              <div style={{ marginTop: 16 }}>
                <Title level={5}>Связанные Кванты</Title>
                {relatedQuants.length === 0 && <Text type="secondary">Нет данных</Text>}
                <Table
                  size="small"
                  rowKey={(r) => r.id}
                  dataSource={relatedQuants}
                  pagination={false}
                  columns={[
                    { title: 'Strength', dataIndex: 'strength', width: 100 },
                    { title: 'Quant ID', dataIndex: 'id', width: 240 },
                    { title: 'Thought (snippet)', dataIndex: 'head' },
                    { title: 'Действия', key: 'act', width: 120, render: (_: any, r: any) => (
                      <Button size="small" onClick={() => openQuantModal(r.id)}>Открыть</Button>
                    )}
                  ]}
                />
              </div>
            </div>
          ) : (
            <Text type="secondary">Данные кванта недоступны</Text>
          )}
        </Spin>
      </Modal>

      {/* Блок Быстрых действий перемещён внутрь «Системные Показатели» */}

      {/* Подвал: Этапы и ошибки */}
      <div style={{ marginTop: 24 }}>
        <Card title="Этапы и ошибки" style={{ marginTop: 16 }} extra={
          <Space>
            <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
              <input type="checkbox" checked={onlySoul} onChange={e => setOnlySoul(e.target.checked)} />
              <span>Только Соул</span>
            </label>
            <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
              <input type="checkbox" checked={onlyErrors} onChange={e => setOnlyErrors(e.target.checked)} />
              <span>Только ошибки</span>
            </label>
            <Button size="small" shape="round" onClick={loadDashboardData}>Обновить</Button>
          </Space>
        }>
          {/* Краткие KPI по активности */}
          <Row gutter={[16, 8]} style={{ marginBottom: 12 }}>
            <Col xs={24} sm={8} md={6}>
              <Statistic title="Событий (последняя выборка)" value={(onlySoul ? recentActivity.filter(a => a.type === 'soul_step' || a.type === 'error') : recentActivity).length} />
            </Col>
            <Col xs={24} sm={8} md={6}>
              <Statistic title="Ошибок" value={(onlySoul ? recentActivity.filter(a => a.type === 'soul_step' || a.type === 'error') : recentActivity).filter(a => a.type === 'error').length} />
            </Col>
            <Col xs={24} sm={8} md={6}>
              <Statistic title="Последнее событие" value={(recentActivity[0]?.timestamp ? new Date(recentActivity[0].timestamp).toLocaleString() : '—')} />
            </Col>
          </Row>
          <Table
            size="small"
            rowKey={(r) => r.id}
            dataSource={(onlySoul ? recentActivity.filter(a => a.type === 'soul_step' || a.type === 'error') : recentActivity)
              .filter(a => !onlyErrors || a.type === 'error')
              .map(a => ({
              id: a.id,
              type: a.type,
              event_type: (a as any).event_type,
              source: (a as any)?.metadata?.provider || null,
              description: a.description,
              timestamp: a.timestamp,
              importance: a.importance
            }))}
            onRow={(record: any) => ({
              onClick: () => {
                const activity = recentActivity.find(a => a.id === record.id) as any;
                // Порядок: если есть trace_id -> трасса, иначе если есть quant_id -> квант, иначе умный фоллбек
                const traceId = activity?.metadata?.trace_id;
                const quantId = activity?.metadata?.quant_id;
                if (traceId) {
                  setTraceId(traceId); setTraceQuantId(undefined); setTraceThreadId(undefined); setTraceViewerOpen(true);
                } else if (quantId) {
                  openQuantModal(String(quantId));
                } else {
                  openQuantModalSmart(activity || { id: record.id, description: record.description, timestamp: record.timestamp, type: record.type, importance: record.importance });
                }
              }
            })}
            columns={[
              { title: 'Время', dataIndex: 'timestamp', width: 180, render: (v: string) => new Date(v).toLocaleString() },
              { title: 'Тип', dataIndex: 'type', width: 120, render: (t: string) => <Tag color={t==='error' ? 'red' : t==='soul_step' ? 'processing' : 'default'}>{t}</Tag> },
              { title: 'Событие', dataIndex: 'event_type', width: 220 },
              { title: 'Источник', dataIndex: 'source', width: 160 },
              { title: 'Важность', dataIndex: 'importance', width: 120, render: (im: string) => <Tag color={getActivityColor(im)}>{im}</Tag> },
              { title: 'Описание', dataIndex: 'description' },
              { title: 'Действия', key: 'actions', width: 120, render: (_: any, record: any) => (
                <Button size="small" type="link">Открыть</Button>
              )}
            ]}
            pagination={{ pageSize: 10 }}
          />
        </Card>

        {/* Блок тестовой генерации удалён */}
      </div>

      {/* Trace Viewer Modal */}
      <TraceViewer
        open={traceViewerOpen}
        onClose={closeTraceViewer}
        traceId={traceId}
        quantId={traceQuantId}
        threadId={traceThreadId}
      />

      {/* Детали события */}
      <Modal
        title="Событие"
        open={eventModalOpen}
        onCancel={() => { setEventModalOpen(false); setSelectedEvent(null); }}
        footer={<Space>
          {(selectedEvent as any)?.metadata?.trace_id && (
            <Button onClick={() => { setTraceId((selectedEvent as any).metadata.trace_id); setEventModalOpen(false); setTraceViewerOpen(true); }}>Открыть трассу</Button>
          )}
          {(selectedEvent as any)?.metadata?.quant_id && (
            <Button type="primary" onClick={() => { const qid = String((selectedEvent as any).metadata.quant_id); setEventModalOpen(false); openQuantModal(qid); }}>Открыть квант</Button>
          )}
        </Space>}
        destroyOnClose
      >
        {selectedEvent ? (
          <div>
            <p><Text strong>Описание:</Text> {selectedEvent.description}</p>
            <p><Text strong>Время:</Text> {new Date(selectedEvent.timestamp).toLocaleString()}</p>
            <p><Text strong>Тип:</Text> {selectedEvent.type}</p>
            {(selectedEvent as any)?.event_type && <p><Text strong>Событие:</Text> {(selectedEvent as any).event_type}</p>}
            {(selectedEvent as any)?.metadata && (
              <div style={{ marginTop: 8 }}>
                <Text strong>Детали:</Text>
                <pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify((selectedEvent as any).metadata, null, 2)}</pre>
              </div>
            )}
          </div>
        ) : <Text type="secondary">Нет данных</Text>}
      </Modal>
    </div>
  );
}
