import React, { useState, useEffect } from "react";
import { Modal, Timeline, Typography, Tag, Spin, Button, Space, Descriptions, Alert } from "antd";
import { ClockCircleOutlined, BugOutlined, CheckCircleOutlined, ExclamationCircleOutlined } from "@ant-design/icons";
import { apiRequest } from "../api";

const { Title, Text } = Typography;

interface TraceEvent {
  ts: string;
  event_type: string;
  description: string;
  quant_id?: string;
  meta: Record<string, any>;
}

interface TraceData {
  trace_id?: string;
  quant_id?: string;
  thread_id?: string;
  events: TraceEvent[];
}

interface TraceViewerProps {
  open: boolean;
  onClose: () => void;
  traceId?: string;
  quantId?: string;
  threadId?: string;
}

export default function TraceViewer({ open, onClose, traceId, quantId, threadId }: TraceViewerProps) {
  const [loading, setLoading] = useState(false);
  const [traceData, setTraceData] = useState<TraceData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loadTraceData = async () => {
    if (!open) return;
    
    try {
      setLoading(true);
      setError(null);
      
      let response: TraceData;
      
      if (traceId) {
        response = await apiRequest(`/admin/soul/trace/by-trace?trace_id=${traceId}`, "GET");
      } else if (quantId) {
        response = await apiRequest(`/admin/soul/trace/by-quant?quant_id=${quantId}`, "GET");
      } else if (threadId) {
        const threadResponse = await apiRequest(`/admin/soul/trace/by-thread?thread_id=${threadId}&limit=10`, "GET");
        if (threadResponse.traces && threadResponse.traces.length > 0) {
          // Берём самую последнюю трассировку
          const latestTrace = threadResponse.traces[0];
          response = await apiRequest(`/admin/soul/trace/by-trace?trace_id=${latestTrace.trace_id}`, "GET");
        } else {
          throw new Error("Трассировки для данного треда не найдены");
        }
      } else {
        throw new Error("Не указан идентификатор для трассировки");
      }
      
      setTraceData(response);
    } catch (err: any) {
      setError(err.message || "Ошибка загрузки трассировки");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTraceData();
  }, [open, traceId, quantId, threadId]);

  const getEventIcon = (eventType: string) => {
    if (eventType.includes("error")) {
      return <BugOutlined style={{ color: "#f5222d" }} />;
    } else if (eventType.includes("done") || eventType.includes("recv")) {
      return <CheckCircleOutlined style={{ color: "#52c41a" }} />;
    } else if (eventType.includes("start") || eventType.includes("send")) {
      return <ClockCircleOutlined style={{ color: "#1890ff" }} />;
    } else {
      return <ExclamationCircleOutlined style={{ color: "#faad14" }} />;
    }
  };

  const getEventColor = (eventType: string) => {
    if (eventType.includes("error")) return "red";
    if (eventType.includes("llm_send")) return "blue";
    if (eventType.includes("llm_recv")) return "green";
    if (eventType.includes("start")) return "cyan";
    if (eventType.includes("done")) return "green";
    if (eventType.includes("saved")) return "purple";
    return "default";
  };

  const formatTimestamp = (ts: string) => {
    try {
      return new Date(ts).toLocaleString("ru-RU", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
        fractionalSecondDigits: 3
      });
    } catch {
      return ts;
    }
  };

  const calculateDuration = (events: TraceEvent[]) => {
    if (events.length < 2) return null;
    
    try {
      const start = new Date(events[0].ts);
      const end = new Date(events[events.length - 1].ts);
      const durationMs = end.getTime() - start.getTime();
      
      if (durationMs < 1000) {
        return `${durationMs}мс`;
      } else {
        return `${(durationMs / 1000).toFixed(2)}с`;
      }
    } catch {
      return null;
    }
  };

  const renderEventDetails = (event: TraceEvent) => {
    const meta = event.meta || {};
    const items = [];

    // Основная информация
    if (meta.provider) items.push({ key: "provider", label: "Провайдер", children: meta.provider });
    if (meta.user_id) items.push({ key: "user_id", label: "User ID", children: meta.user_id });
    if (meta.thread_id) items.push({ key: "thread_id", label: "Thread ID", children: meta.thread_id });
    
    // LLM специфичная информация
    if (meta.system_len) items.push({ key: "system_len", label: "Длина системного промпта", children: meta.system_len });
    if (meta.user_len) items.push({ key: "user_len", label: "Длина пользовательского сообщения", children: meta.user_len });
    if (meta.response_len) items.push({ key: "response_len", label: "Длина ответа", children: meta.response_len });
    if (meta.max_tokens) items.push({ key: "max_tokens", label: "Max tokens", children: meta.max_tokens });
    if (meta.temperature) items.push({ key: "temperature", label: "Temperature", children: meta.temperature });
    
    // Ошибки
    if (meta.error_type) items.push({ key: "error_type", label: "Тип ошибки", children: meta.error_type });
    if (meta.error_message) items.push({ key: "error_message", label: "Сообщение об ошибке", children: meta.error_message });
    
    // Энергия и веса
    if (meta.energy_weight) items.push({ key: "energy_weight", label: "Энергетический вес", children: meta.energy_weight });
    if (meta.final_energy_weight) items.push({ key: "final_energy_weight", label: "Финальный энергетический вес", children: meta.final_energy_weight });

    return items.length > 0 ? (
      <Descriptions size="small" column={1} items={items} style={{ marginTop: 8 }} />
    ) : null;
  };

  const title = traceId 
    ? `Трассировка ${traceId.slice(0, 8)}...`
    : quantId 
    ? `Трассировка кванта ${quantId.slice(0, 8)}...`
    : threadId
    ? `Трассировка треда ${threadId.slice(0, 8)}...`
    : "Трассировка";

  return (
    <Modal
      title={title}
      open={open}
      onCancel={onClose}
      width={900}
      footer={
        <Space>
          <Button onClick={onClose}>Закрыть</Button>
          <Button type="primary" onClick={loadTraceData} loading={loading}>
            Обновить
          </Button>
        </Space>
      }
      destroyOnClose
    >
      <Spin spinning={loading}>
        {error && (
          <Alert
            message="Ошибка загрузки"
            description={error}
            type="error"
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}
        
        {traceData && (
          <>
            {/* Сводная информация */}
            <div style={{ marginBottom: 16, padding: 12, backgroundColor: "#f5f5f5", borderRadius: 6 }}>
              <Space direction="vertical" size="small" style={{ width: "100%" }}>
                {traceData.trace_id && (
                  <Text><strong>Trace ID:</strong> <Text code>{traceData.trace_id}</Text></Text>
                )}
                {traceData.quant_id && (
                  <Text><strong>Quant ID:</strong> <Text code>{traceData.quant_id}</Text></Text>
                )}
                <Text><strong>Событий:</strong> {traceData.events.length}</Text>
                {traceData.events.length > 0 && (
                  <>
                    <Text><strong>Начало:</strong> {formatTimestamp(traceData.events[0].ts)}</Text>
                    <Text><strong>Конец:</strong> {formatTimestamp(traceData.events[traceData.events.length - 1].ts)}</Text>
                    {calculateDuration(traceData.events) && (
                      <Text><strong>Длительность:</strong> {calculateDuration(traceData.events)}</Text>
                    )}
                  </>
                )}
              </Space>
            </div>

            {/* Таймлайн событий */}
            <Timeline
              mode="left"
              items={traceData.events.map((event, index) => ({
                dot: getEventIcon(event.event_type),
                children: (
                  <div key={index}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
                      <Space>
                        <Tag color={getEventColor(event.event_type)}>{event.event_type}</Tag>
                        <Text type="secondary" style={{ fontSize: 12 }}>
                          {formatTimestamp(event.ts)}
                        </Text>
                      </Space>
                      {event.quant_id && (
                        <Text code style={{ fontSize: 11 }}>
                          {event.quant_id.slice(0, 8)}...
                        </Text>
                      )}
                    </div>
                    <Text>{event.description}</Text>
                    {renderEventDetails(event)}
                  </div>
                )
              }))}
            />

            {traceData.events.length === 0 && (
              <div style={{ textAlign: "center", padding: 40 }}>
                <Text type="secondary">События трассировки не найдены</Text>
              </div>
            )}
          </>
        )}
      </Spin>
    </Modal>
  );
}
